const payload = $input.first().json;
const campaignId = payload.campaignId || `camp_${Date.now()}`;
const eventId = payload.eventId || '';
const eventName = payload.eventName || 'Academic Event';
const templateSubject = payload.subject || 'Your Certificate - {{event_name}}';
const templateMessage = payload.message || 'Hi {{name}},\n\nCongratulations on participating in {{event_name}}.\n\nPlease find your certificate attached.\n\nBest regards,\nEvent Organizing Team';
const rawRecipients = payload.recipients || [];

return rawRecipients.map((rec, index) => {
  const name = rec.name || 'Participant';
  const email = rec.email || '';
  const fileName = rec.fileName || `${name}.pdf`;
  const fileUrl = rec.fileUrl || '';

  const personalizedSubject = templateSubject
    .replace(/\{\{name\}\}/g, name)
    .replace(/\{\{event_name\}\}/g, eventName);

  const personalizedMessage = templateMessage
    .replace(/\{\{name\}\}/g, name)
    .replace(/\{\{event_name\}\}/g, eventName);

  return {
    json: {
      index,
      campaignId,
      eventId,
      eventName,
      name,
      email,
      fileName,
      fileUrl,
      subject: personalizedSubject,
      message: personalizedMessage
    }
  };
});

const items = $input.all();
const failedFiles = [];
let success = 0;
let failed = 0;

for (const item of items) {
  const data = item.json;
  if (data.status === 'SENT' || !data.error) {
    success++;
  } else {
    failed++;
    failedFiles.push({
      fileName: data.fileName || 'unknown.pdf',
      email: data.email || 'unknown@domain.com',
      error: data.error || 'Gmail delivery error'
    });
  }
}

return [
  {
    json: {
      total: success + failed,
      success,
      failed,
      failedFiles
    }
  }
];
